const products = [
 {id:'armour',name:'The Knight’s Armour',category:'armour',group:'heritage',label:'Full body armour',image:'armour',price:895,old:1040,tag:'THE COLLECTOR’S EDIT',sub:'Polished steel · Full display suit',material:'Polished steel',size:'Approx. 185 cm tall',weight:'Approx. 28 kg',description:'A commanding medieval-inspired silhouette, with articulated plates and a beautifully polished finish. An extraordinary centrepiece for a collection or a character-filled interior.',options:['Polished steel','Antiqued steel']},
 {id:'chandelier',name:'The Versailles Chandelier',category:'chandeliers',group:'lighting',label:'Brass chandeliers',image:'chandelier',price:385,tag:'ATELIER FAVORITE',sub:'Antique brass · Six-arm silhouette',material:'Brass-tone metal',size:'Approx. 65 × 70 cm',weight:'Approx. 7 kg',description:'Sweeping arms, ornate details and a soft golden patina. This vintage-inspired chandelier brings a graceful sense of occasion to dining rooms and entryways.',options:['Antique brass','Aged gold']},
 {id:'shield',name:'The Heraldic Shield',category:'shields',group:'heritage',label:'Medieval shields',image:'shields',price:145,tag:'HERITAGE ESSENTIAL',sub:'Steel & heraldic detail · Display piece',material:'Steel with decorative finish',size:'Approx. 60 × 45 cm',weight:'Approx. 4 kg',description:'Bold heraldic forms and a rich, timeworn finish. A medieval-inspired decorative shield, made for striking wall displays and thoughtfully curated collections.',options:['Heraldic design','Round shield']},
 {id:'lights',name:'The Brass Lighting Ensemble',category:'lights',group:'lighting',label:'Vintage lights',image:'lights',price:245,sub:'Warm brass · Lamp & sconce concept set',material:'Brass-tone metal',size:'Lamp approx. 48 cm tall',weight:'Approx. 5 kg',description:'A characterful pairing of warm brass lighting forms. This concept ensemble illustrates how a table lamp and wall accents can bring a beautifully layered glow to a space.',options:['Antique brass','Warm brass']},
 {id:'accessories',name:'The Armourer’s Collection',category:'accessories',group:'heritage',label:'Armour accessories',image:'accessories',price:195,tag:'THE FINISHING TOUCH',sub:'Helmet, gauntlets & leather detail',material:'Steel & leather accents',size:'Display collection',weight:'Approx. 6 kg',description:'The small details that complete a world. A medieval-inspired helmet, articulated gauntlets and leather accents, presented together as a collector’s display concept.',options:['Polished finish','Aged finish']}
];
const rates={USD:1,CAD:1.36,GBP:.79,INR:84};let currency='USD';let filter='all',category='all',query='',sorting='featured';
function restore(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
let cart=restore('azeem-cart',[]).filter(x=>products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99);let saved=restore('azeem-saved',[]).filter(id=>products.some(p=>p.id===id));
const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency,maximumFractionDigits:0}).format(n*rates[currency]);const product=id=>products.find(p=>p.id===id);const image=p=>`assets/${p.image}-1024.webp`;
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function persist(){try{localStorage.setItem('azeem-cart',JSON.stringify(cart));localStorage.setItem('azeem-saved',JSON.stringify(saved))}catch{}$('#cart-count').textContent=cart.reduce((n,x)=>n+x.qty,0);$('#saved-count').textContent=saved.length}
function render(){let list=products.filter(p=>(category==='all'||p.category===category)&&(filter==='all'||p.group===filter||(filter==='saved'&&saved.includes(p.id)))&&(!query||`${p.name} ${p.label} ${p.sub} ${p.material}`.toLowerCase().includes(query)));if(sorting!=='featured')list.sort((a,b)=>sorting==='low'?a.price-b.price:b.price-a.price);$('#result-summary').textContent=`${String(list.length).padStart(2,'0')} PIECES${query?' · SEARCH RESULTS':''}${filter==='saved'?' · YOUR FAVORITES':''}`;$('#products').innerHTML=list.map(p=>`<article class="product"><div class="product-photo"><a href="#product-${p.id}" aria-label="View ${p.name}"><img src="${image(p)}" alt="${p.sub}" loading="lazy"></a>${p.tag?`<span class="tag">${p.tag}</span>`:''}<button class="favorite ${saved.includes(p.id)?'saved':''}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${p.name}" aria-pressed="${saved.includes(p.id)}" data-save="${p.id}">${saved.includes(p.id)?'♥':'♡'}</button><button class="quick-add" aria-label="Add ${p.name} to bag" data-add="${p.id}">+</button></div><div class="product-category">${p.label}</div><h3><a href="#product-${p.id}">${p.name}</a></h3><p class="product-sub">${p.sub}</p><div class="price-row"><strong>${money(p.price)}</strong>${p.old?`<span class="old-price">${money(p.old)}</span>`:''}<span class="fine">${currency}</span></div></article>`).join('')||'<div class="no-results">No pieces found. Try another search or collection.<br><button id="reset-filters">Explore all pieces ↗</button></div>';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter)});document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));persist()}
function shop(next='all'){filter=next;category='all';query='';$('#search').value='';render();$('#collection').scrollIntoView({behavior:'smooth'})}
function show(id){const d=$(id);if(!d.open)d.showModal()}
function detail(id){const p=product(id);if(!p)return;$('#product-detail').innerHTML=`<div class="detail-grid"><img class="detail-photo" src="${image(p)}" alt="${p.sub}"><div class="detail-copy"><div class="eyebrow">${p.label.toUpperCase()}</div><h2>${p.name}</h2><p>${p.description}</p><div class="price-row">${money(p.price)} <span class="fine">${currency} · Sample price</span></div><label for="finish">Choose a finish / style</label><select id="finish">${p.options.map(x=>`<option>${x}</option>`).join('')}</select><div class="detail-buttons"><button class="button" id="detail-add" data-id="${p.id}">Add to bag <span>+</span></button><button class="button outline" id="buy-now" data-id="${p.id}">Buy now ↗</button></div><div class="specs"><div><span>Material</span>${p.material}</div><div><span>Dimensions</span>${p.size}</div><div><span>Weight</span>${p.weight}</div></div><p class="fine">Concept product and imagery. Dimensions, materials, stock and prices are illustrative. Armour is presented for decorative display. Lighting electrical specifications must be confirmed before sale.</p><button class="text-link" data-info="shipping">International shipping & returns ↗</button></div></div>`;show('#product-dialog')}
function add(id,option){const p=product(id);option=option||p.options[0];const line=cart.find(x=>x.id===id&&x.option===option);if(line){if(line.qty>=99){toast('Maximum quantity reached');return}line.qty++}else cart.push({id,option,qty:1});persist();toast(`${p.name} added to your bag`)}
const subtotal=()=>cart.reduce((n,x)=>n+product(x.id).price*x.qty,0);
function renderBag(){const el=$('#bag-content');if(!cart.length){el.innerHTML='<div class="empty"><h3>A little room for wonder.</h3><p>Your shopping bag is waiting for its first extraordinary find.</p><button class="button wide" id="continue-shopping">Explore the collection ↗</button></div>';return}el.innerHTML=cart.map((x,i)=>{const p=product(x.id);return `<div class="bag-line"><img src="${image(p)}" alt="${p.name}"><div><h3>${p.name}</h3><small>${x.option}</small><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="Decrease ${p.name} quantity">−</button><span>${x.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Increase ${p.name} quantity">+</button></div></div><div>${money(p.price*x.qty)}<button class="remove" data-remove="${i}" aria-label="Remove ${p.name}">Remove</button></div></div>`}).join('')+`<div class="totals"><div><span>Subtotal</span><strong>${money(subtotal())}</strong></div><div><span>Shipping</span><span>Calculated at checkout</span></div></div><button class="button wide" id="start-checkout">Continue to checkout ↗</button><p class="fine" style="margin-top:15px;text-align:center">Demo checkout · No payment will be collected</p>`}
const shippingRates={US:85,CA:95,GB:75};function checkout(){if(!cart.length)return;$('#bag-dialog').close();$('#product-dialog').close();$('#checkout-content').innerHTML=`<div class="eyebrow">THE LAST STEP TO SOMETHING SPECIAL</div><h2>Make it yours.</h2><div class="demo-banner">You’re exploring a demo. Use sample details below. No payment is collected, no order is sent, and nothing you enter is saved.</div><div class="checkout-grid"><form id="checkout-form"><label>First name<input name="first" autocomplete="given-name" required placeholder="Alex" maxlength="60"></label><label>Last name<input name="last" autocomplete="family-name" required placeholder="Morgan" maxlength="60"></label><label class="full">Email address<input type="email" name="email" required placeholder="alex@example.com" maxlength="150"></label><label class="full">Street address<input name="address" required placeholder="123 Sample Street" maxlength="200"></label><label>City<input name="city" required placeholder="New York" maxlength="80"></label><label>State / province / county<input name="region" required placeholder="New York" maxlength="80"></label><label>Postal / ZIP code<input name="postal" required placeholder="10001" maxlength="20"></label><label>Ship to<select name="country" id="country"><option value="US">United States</option><option value="CA">Canada</option><option value="GB">United Kingdom</option></select></label><div class="full fine">Payment mode: demonstration only. Illustrative shipping and delivery estimates. Import duties and taxes are excluded and require confirmation before a real order.</div><button class="button full wide" type="submit">Place demo order ↗</button></form><aside class="order-summary"><h3>Your collection</h3>${cart.map(x=>`<div class="summary-line"><span>${product(x.id).name} × ${x.qty}</span><strong>${money(product(x.id).price*x.qty)}</strong></div>`).join('')}<div class="totals"><div><span>Subtotal</span><span>${money(subtotal())}</span></div><div><span>Sample shipping</span><span id="shipping-price">${money(85)}</span></div><div class="grand"><span>Total</span><strong id="checkout-total">${money(subtotal()+85)}</strong></div></div><p class="fine" id="delivery-estimate">Sample delivery: 14–21 business days to the USA.</p></aside></div>`;show('#checkout-dialog');$('#country').addEventListener('change',e=>{const c=e.target.value;$('#shipping-price').textContent=money(shippingRates[c]);$('#checkout-total').textContent=money(subtotal()+shippingRates[c]);$('#delivery-estimate').textContent=`Sample delivery: 14–21 business days to ${c==='US'?'the USA':c==='CA'?'Canada':'the UK'}.`});$('#checkout-form').addEventListener('submit',e=>{e.preventDefault();cart=[];persist();$('#checkout-content').innerHTML='<div class="success"><div class="success-mark">✧</div><div class="eyebrow">A LITTLE PREVIEW OF WHAT’S TO COME</div><h2>Your demo order is complete.</h2><p>You’ve experienced the full journey, from discovery to checkout. No payment was taken and no real order was placed. Your form details have been discarded.</p><button class="button" id="done-shopping">Back to the collection ↗</button></div>'})}
const info={shipping:['Across borders. With care.','This demo supports checkout destinations in the United States, Canada and the United Kingdom. Sample flat-rate shipping is US$85, US$95 and US$75 respectively, with an illustrative 14–21 business day delivery window.','Live shipping rates, dispatch times, insurance, product eligibility, import duties and taxes must be confirmed before launch. Returns and damage procedures will be published with the final store policies.'],help:['A personal touch, always.','For product details, custom finishes or international delivery questions, the finished store can connect customers directly to the atelier through WhatsApp and email.','Contact details and customer support channels are awaiting owner verification. This demo does not send enquiries.'],care:['Made to be appreciated.','For display steel pieces, gently dust with a soft, dry cloth. Avoid moisture and abrasive cleaners. Follow the final product-specific care guide once materials and finishes are confirmed.','For brass lighting, disconnect power before cleaning. Electrical installation and voltage compatibility should be checked by a qualified professional.'],privacy:['A thoughtfully simple demo.','Cart selections and favorites are stored only in this browser. Checkout form entries are neither transmitted nor saved, and are removed when the demo checkout finishes or closes.','All products, prices, specifications, delivery rates and imagery are illustrative concepts. Currency amounts use fixed demonstration conversion rates. Payment processing, live inventory, real orders and customer accounts are not connected.']};
function information(type){const [title,...paras]=info[type]||info.help;$('#info-content').innerHTML=`<div class="eyebrow">AZEEM ATELIER · GOOD TO KNOW</div><h2>${title}</h2>${paras.map(p=>`<p>${p}</p>`).join('')}`;show('#info-dialog')}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.matches('.close')){b.closest('dialog').close();return}if(b.dataset.category){category=b.dataset.category;filter='all';query='';$('#search').value='';render();$('#collection').scrollIntoView();return}if(b.dataset.filter){filter=b.dataset.filter;category='all';render();return}if(b.dataset.world){shop(b.dataset.world);return}if(b.dataset.info){information(b.dataset.info);return}if(b.dataset.save){const id=b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];render();return}if(b.dataset.add){add(b.dataset.add);return}if(b.dataset.qty!==undefined){const i=Number(b.dataset.qty);cart[i].qty=Math.min(99,cart[i].qty+Number(b.dataset.delta));if(cart[i].qty<1)cart.splice(i,1);persist();renderBag();return}if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);persist();renderBag();return}if(b.id==='cart-button'){renderBag();show('#bag-dialog')}if(b.id==='saved-button')shop('saved');if(['reset-filters','continue-shopping','done-shopping'].includes(b.id)){document.querySelectorAll('dialog[open]').forEach(d=>d.close());shop()}if(b.id==='detail-add')add(b.dataset.id,$('#finish').value);if(b.id==='buy-now'){add(b.dataset.id,$('#finish').value);checkout()}if(b.id==='start-checkout')checkout();if(b.getAttribute('href')?.startsWith('#product-')){e.preventDefault();detail(b.getAttribute('href').slice(9))}});
$('#search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();filter='all';category='all';render()});$('#search-form').addEventListener('submit',e=>{e.preventDefault();$('#collection').scrollIntoView()});$('#sort').addEventListener('change',e=>{sorting=e.target.value;render()});$('#currency').addEventListener('change',e=>{currency=e.target.value;render();if($('#bag-dialog').open)renderBag()});document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});$('#checkout-dialog').addEventListener('close',()=>{$('#checkout-content').innerHTML=''});render();
